<template><view class="detail-page"><view v-if="loading" class="card state-card">正在加载文章…</view><template v-else-if="article"><view class="detail-meta">{{ article.source }} · {{ article.publishDate }}</view><view class="detail-title">{{ article.title }}</view><view class="article-tags"><text v-for="tag in article.tags" :key="tag">{{ tag }}</text></view><view class="detail-content" user-select>{{ article.content }}</view><view class="detail-footer"><button class="auth-button" @tap="train">开始三刀拆解</button></view></template><view v-else class="card state-card">文章不存在或尚未发布</view></view></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import Taro, { useRouter } from '@tarojs/taro'; import { api, type RmrbArticle } from '@/api'; import { showToast } from '@/utils/platform'; const router=useRouter(); const article=ref<RmrbArticle|null>(null); const loading=ref(true); async function load(){const id=String(router.params?.id||'');if(!id){loading.value=false;return}const response=await api.getArticle(id);loading.value=false;if(response.code===0&&response.data)article.value=response.data;else showToast(response.message||'文章加载失败')} function train(){Taro.switchTab({url:'/pages/training/index'})} onMounted(()=>void load())</script>
